import cv2
import numpy as np

def identify_criminals(image_path):
    try:
        img = cv2.imread(image_path)
        if img is None:
            print("Could not load image.")
            return False

        # Check if the image is a face
        if img.shape[1] == 3:
            face_count = 0
            for i in range(img.shape[0]):
                for j in range(img.shape[1]):
                    if img[i, j] == 1:
                        face_count += 1
            if face_count == 1:
                print("The image contains only one face.")
                return True
        else:
            print("Could not load image.")
            return False
    except Exception as e:
        print(f"Error loading image: {e}")
        return False

# Example usage:
image_path = "image.jpg"
identify_criminals(image_path)
